import { gsap } from 'gsap';
import {
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { mix, smoothstep, vec3, positionLocal, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'bento-metrics-grid';

  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#101017' },
      { at: 1, hex: '#1a1a22' },
    ],
  };

  const typography = config?.intent?.visualSpec?.typography ?? {
    value: { fontSize: 68 },
    valueLarge: { fontSize: 124 },
    label: { fontSize: 18 },
    caption: { fontSize: 18 },
  };

  const disposables = [];
  const timelines = [];

  const toVec3 = (hex) => {
    const c = new THREE.Color(hex);
    return vec3(c.r, c.g, c.b);
  };

  // ---------- BACKDROP (stage, no flat void) ----------
  const stopA = colors.gradientStops?.[0]?.hex ?? '#101017';
  const stopB = colors.gradientStops?.[1]?.hex ?? '#1a1a22';
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(toVec3(stopA), toVec3(stopB), uv().y);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---------- Rim / accent light (node-local) ----------
  const rimLight = new THREE.DirectionalLight(new THREE.Color(colors.accent ?? '#ff2a38'), 0.7);
  rimLight.position.set(-3, 2, 4);
  root.add(rimLight);
  const fillRim = new THREE.DirectionalLight(new THREE.Color(colors.paper ?? '#e8ecf2'), 0.5);
  fillRim.position.set(3, -1.5, 3.5);
  root.add(fillRim);
  disposables.push(() => { root.remove(rimLight); root.remove(fillRim); });

  // ---------- helpers ----------
  function roundedRectShape(w, h, r) {
    const shape = new THREE.Shape();
    const x = -w / 2, y = -h / 2;
    shape.moveTo(x + r, y);
    shape.lineTo(x + w - r, y);
    shape.quadraticCurveTo(x + w, y, x + w, y + r);
    shape.lineTo(x + w, y + h - r);
    shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    shape.lineTo(x + r, y + h);
    shape.quadraticCurveTo(x, y + h, x, y + h - r);
    shape.lineTo(x, y + r);
    shape.quadraticCurveTo(x, y, x + r, y);
    return shape;
  }

  function cellSurfaceMaterial(width, height) {
    const mat = new MeshPhysicalNodeMaterial();
    const nx = positionLocal.x.div(width).add(0.5);
    const ny = positionLocal.y.div(height).add(0.5).oneMinus();
    const t = nx.add(ny).mul(0.5);
    const base = mix(toVec3(stopA), toVec3(stopB), t);
    const bandStart = 0.325, bandCenter = 0.4, bandEnd = 0.475;
    const rising = smoothstep(bandStart, bandCenter, t);
    const falling = smoothstep(bandCenter, bandEnd, t);
    const pulse = rising.sub(falling);
    mat.colorNode = base.add(pulse.mul(0.06));
    mat.roughness = 0.5;
    mat.metalness = 0.45;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.35;
    return mat;
  }

  function makeSlabMesh(width, height) {
    const shape = roundedRectShape(width, height, 0.06);
    const geo = new THREE.ExtrudeGeometry(shape, {
      depth: 0.02,
      bevelEnabled: true,
      bevelThickness: 0.02,
      bevelSize: 0.04,
      bevelSegments: 4,
      steps: 1,
      curveSegments: 8,
    });
    geo.translate(0, 0, -0.03);
    const mat = cellSurfaceMaterial(width, height);
    const mesh = new THREE.Mesh(geo, mat);
    disposables.push(() => { geo.dispose(); mat.dispose(); });
    return mesh;
  }

  function tickBar(accentHex) {
    const geo = new THREE.PlaneGeometry(0.4, 0.05);
    const mat = new MeshStandardNodeMaterial();
    const accentVec = toVec3(accentHex);
    mat.colorNode = accentVec.mul(0.6);
    mat.emissiveNode = accentVec.mul(1.3);
    mat.roughness = 0.4;
    mat.metalness = 0.1;
    const mesh = new THREE.Mesh(geo, mat);
    disposables.push(() => { geo.dispose(); mat.dispose(); });
    return mesh;
  }

  // ---------- text content bridging ----------
  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [
    { text: 'ATELIER METRICS / Q2 2026', role: 'caption' },
    { text: '0.002 mm', role: 'valueLarge' },
    { text: 'Case tolerance, CNC pass', role: 'label' },
    { text: '38 h', role: 'value' },
    { text: 'Power reserve, NA-01', role: 'label' },
    { text: '214', role: 'value' },
    { text: 'Components per calibre', role: 'label' },
  ];

  const captionItem = items.find((i) => i.role === 'caption') ?? items[0];
  const rest = items.filter((i) => i !== captionItem);
  // expect order: valueLarge,label, value,label, value,label
  const statBlocks = [];
  for (let i = 0; i < rest.length; i += 2) {
    statBlocks.push({ value: rest[i], label: rest[i + 1] });
  }
  while (statBlocks.length < 3) statBlocks.push({ value: { text: '' }, label: { text: '' } });

  const accentHex = colors.accent ?? '#ff2a38';
  const paperHex = colors.paper ?? '#e8ecf2';

  // ---------- header caption ----------
  const capFontSize = captionItem?.typography?.fontSize ?? typography.caption?.fontSize ?? 18;
  const captionText = ctx.fontAtlas.createText(captionItem?.text ?? 'ATELIER METRICS / Q2 2026', {
    fontSize: capFontSize,
    color: paperHex,
    align: 'left',
    letterSpacingPx: capFontSize * 0.12,
  });
  captionText.position.set(-2.75, 2.25, 0.05);
  root.add(captionText);

  // small foreground accent rule under header (depth plane #3)
  const ruleGeo = new THREE.PlaneGeometry(0.9, 0.02);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = toVec3(accentHex);
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-2.3, 2.05, 0.3);
  root.add(rule);
  disposables.push(() => { ruleGeo.dispose(); ruleMat.dispose(); });

  // ---------- grid layout ----------
  const gridW = 5.5, gridH = 3.5, gutter = 0.25;
  const domW = 3.25, domH = 3.5;
  const secW = 2.0, secH = 1.625;

  const domX = -gridW / 2 + domW / 2;
  const domY = 0;

  const secX = -gridW / 2 + domW + gutter + secW / 2;
  const secTopY = gridH / 2 - secH / 2;
  const secBotY = -gridH / 2 + secH / 2;

  const cellDefs = [
    { w: domW, h: domH, x: domX, y: domY, dominant: true, block: statBlocks[0], valueFontSize: typography.valueLarge?.fontSize ?? 124 },
    { w: secW, h: secH, x: secX, y: secTopY, dominant: false, block: statBlocks[1], valueFontSize: typography.value?.fontSize ?? 68 },
    { w: secW, h: secH, x: secX, y: secBotY, dominant: false, block: statBlocks[2], valueFontSize: typography.value?.fontSize ?? 68 },
  ];

  const cellMeshes = [];
  const cellOriginalY = [];

  cellDefs.forEach((def, idx) => {
    const cellGroup = new THREE.Group();
    cellGroup.position.set(def.x, def.y, 0);

    const slab = makeSlabMesh(def.w, def.h);
    slab.userData.isCell = true;
    slab.userData.cellIndex = idx;
    cellGroup.add(slab);
    cellMeshes.push(slab);

    const tick = tickBar(accentHex);
    tick.position.set(-def.w / 2 + 0.7, def.h / 2 - 0.525, 0.05);
    cellGroup.add(tick);

    const labelFontSize = def.block.label?.typography?.fontSize ?? typography.label?.fontSize ?? 18;
    const valueText = ctx.fontAtlas.createText(def.block.value?.text ?? '', {
      fontSize: def.valueFontSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: def.valueFontSize * -0.005,
    });
    const labelText = ctx.fontAtlas.createText(def.block.label?.text ?? '', {
      fontSize: labelFontSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: labelFontSize * 0.08,
    });

    if (def.dominant) {
      valueText.position.set(-def.w / 2 + 0.5, -0.1, 0.05);
      labelText.position.set(-def.w / 2 + 0.5, -0.6, 0.05);
    } else {
      valueText.position.set(-def.w / 2 + 0.5, def.h / 2 - 0.95, 0.05);
      labelText.position.set(-def.w / 2 + 0.5, -def.h / 2 + 0.35, 0.05);
    }

    cellGroup.add(valueText);
    cellGroup.add(labelText);

    root.add(cellGroup);

    cellOriginalY.push(def.y);
    slab.userData.parentGroup = cellGroup;
    slab.userData.baseY = def.y;
  });

  // ---------- entrance: stagger-cards / fade-up, dominant first ----------
  cellDefs.forEach((def, idx) => {
    const group = cellMeshes[idx].userData.parentGroup;
    group.traverse((obj) => {
      if (obj.material) {
        obj.material.transparent = true;
        obj.material.opacity = 0;
      }
    });
    group.position.y = def.y + 0.2;
  });

  const enterTl = gsap.timeline({ delay: 0.05 });
  cellDefs.forEach((def, idx) => {
    const group = cellMeshes[idx].userData.parentGroup;
    const opacityTarget = { v: 0 };
    enterTl.to(group.position, {
      y: def.y,
      duration: 0.5,
      ease: 'power2.out',
    }, idx * 0.08);
    enterTl.to(opacityTarget, {
      v: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => {
        group.traverse((obj) => {
          if (obj.material) obj.material.opacity = opacityTarget.v;
        });
      },
    }, idx * 0.08);
  });
  timelines.push(enterTl);

  // ---------- hover: press-down / weighted-settle ----------
  function findCellFromEvent(event) {
    const obj = event?.object;
    if (!obj) return null;
    let cur = obj;
    while (cur) {
      if (cur.userData?.isCell) return cur;
      cur = cur.parent;
    }
    return null;
  }

  const activeTweens = new Map();

  root.userData.handlers = {
    onPointerOver: (event) => {
      const cell = findCellFromEvent(event);
      if (!cell) return;
      const group = cell.userData.parentGroup;
      const prev = activeTweens.get(group);
      if (prev) prev.kill();
      const tw = gsap.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
      activeTweens.set(group, tw);
    },
    onPointerOut: (event) => {
      const cell = findCellFromEvent(event);
      if (!cell) return;
      const group = cell.userData.parentGroup;
      const prev = activeTweens.get(group);
      if (prev) prev.kill();
      group.scale.set(1.04, 1.04, 1.04);
      const tw = gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.9,
        ease: 'power4.out',
      });
      activeTweens.set(group, tw);
    },
    onPointerDown: (event) => {
      const cell = findCellFromEvent(event);
      if (!cell) return;
      const group = cell.userData.parentGroup;
      const prev = activeTweens.get(group);
      if (prev) prev.kill();
      const tw = gsap.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
      activeTweens.set(group, tw);
    },
    onPointerUp: (event) => {
      const cell = findCellFromEvent(event);
      if (!cell) return;
      const group = cell.userData.parentGroup;
      const prev = activeTweens.get(group);
      if (prev) prev.kill();
      const tw = gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.9,
        ease: 'power4.out',
      });
      activeTweens.set(group, tw);
    },
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    activeTweens.forEach((tw) => tw.kill());
    activeTweens.clear();
    disposables.forEach((fn) => {
      try { fn(); } catch (e) { /* noop */ }
    });
    root.traverse((obj) => {
      if (obj.geometry && typeof obj.geometry.dispose === 'function') obj.geometry.dispose();
      if (obj.material && typeof obj.material.dispose === 'function') obj.material.dispose();
    });
    while (root.children.length) root.remove(root.children[0]);
  };

  return root;
}
